CREATE FUNCTION organization_account_fields() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, synapse AS $$
BEGIN
  IF json_valid(NEW.org_roles)=0 OR json_valid(NEW.org_proposed_roles)=0 OR NEW.org_mode NOT IN ('legacy','managed') OR NEW.scientific_qualified NOT IN (0,1) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'invalid organizational profile'; END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER organization_account_fields BEFORE UPDATE OF org_roles,org_proposed_roles,org_mode,scientific_qualified,permissions ON staff_accounts FOR EACH ROW EXECUTE FUNCTION organization_account_fields();
CREATE FUNCTION organization_qualified_approval() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, synapse AS $$
BEGIN
  IF NEW.org_mode='managed' AND EXISTS(SELECT 1 FROM json_each(NEW.permissions) WHERE value='science_approve') AND (NEW.scientific_qualified!=1 OR NOT EXISTS(SELECT 1 FROM json_each(NEW.org_roles) WHERE value='research_manager')) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'qualified research manager required for final approval'; END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER organization_qualified_approval BEFORE UPDATE OF org_roles,org_mode,scientific_qualified,permissions ON staff_accounts FOR EACH ROW EXECUTE FUNCTION organization_qualified_approval();
